  const goodDays = sales.filter((x) => x >= 10).length;
  return (goodDays * (goodDays + 1)) / 2;
}

solutions.java:
class CountSubarraysWithGoodStartAndEnding {
  public long solve(int[] sales) {
    int goodDays = 0;
    for (int x : sales) {
      if (x >= 10) {
        goodDays++;
      }
    }
    return (long) goodDays * (goodDays + 1) / 2;
  }
}

